#include "TakeRecovery.h"
static bool waitTake(const std::function<bool()>& ready){for(int i=0;i<1500;++i){if(ready())return true;Thread::sleep(2);}return ready();}
static bool recordedCheckpoint(const File& workspace,TakeCheckpoint& c,int channels=2,int count=16003,bool longTitle=false){auto p=emptyProject();if(longTitle)p.title=String::repeatedString("z",200);p.bpm=120;p.patterns[0].lanes[7]={{0,2,67,.7f}};if(prepareTakeCheckpoint(p,workspace,workspace.getChildFile("data/Recordings"),7,4,8000,channels,80000,c).failed())return false;Recorder recorder;if(recorder.start(c.audio(),8000,channels,10,&c).failed())return false;AudioBuffer<float> input(2,257);for(int i=0;i<257;++i){input.setSample(0,i,.25f);input.setSample(1,i,-.125f);}for(int at=0;at<count;at+=257){recorder.capture(input.getReadPointer(0),input.getReadPointer(1),jmin(257,count-at));Thread::sleep(1);}return recorder.finish().wasOk()&&recorder.flushedFrames()==(uint64_t)count&&readTakeCheckpoint(c.directory,c).wasOk();}
static void testTakeRecovery(const File& root){
    auto workspace=root.getNonexistentChildFile("take-recovery","",false);workspace.createDirectory();auto recordings=workspace.getChildFile("data/Recordings");TakeCheckpoint c;expect(recordedCheckpoint(workspace,c),"record a real stereo PCM24 take with flushed recovery checkpoints");if(c.frames==0)return;
    expect(c.frames==16003&&c.dataOffset>=44&&c.header.getSize()==(size_t)c.dataOffset&&c.tailHash.length()==64,"final acknowledgement records exact frames header and bounded tail identity");
    Project before;expect(loadProject(c.directory.getChildFile("session.pulse"),before).wasOk()&&before.patterns[0].lanes[7][0].pitch==67&&before.clips.empty(),"take session snapshot preserves original music before captured audio is inserted");
    auto original=projectFileToken(c.directory.getChildFile("session.pulse"));MemoryBlock audioBefore;c.audio().loadFileAsData(audioBefore);File recovered;expect(recoverTakeCheckpoint(c,recovered).wasOk()&&recovered.existsAsFile(),"recovery publishes a separate project and audio copy");Project restored;expect(loadProject(recovered,restored).wasOk()&&restored.songMode&&!restored.loop&&restored.clips.size()==1&&restored.clips[0].track==7&&restored.clips[0].beat==4&&std::abs(restored.clips[0].length-4.00075)<1e-9&&restored.patterns[0].lanes[7]==before.patterns[0].lanes[7],"recovered project restores original notes and exact take lane position and duration");
    auto copied=recovered.getSiblingFile("recovered.wav");MemoryBlock audioAfter;copied.loadFileAsData(audioAfter);expect(audioAfter.getSize()>=44+c.frames*6&&std::memcmp((char*)audioBefore.getData()+c.dataOffset,(char*)audioAfter.getData()+44,(size_t)c.frames*6)==0,"recovery preserves every acknowledged PCM sample byte without float requantization");MemoryBlock unchanged;c.audio().loadFileAsData(unchanged);expect(unchanged==audioBefore&&projectFileToken(c.directory.getChildFile("session.pulse"))==original,"recovery leaves original WAV and session snapshot bytes unchanged");
    File same;expect(recoverTakeCheckpoint(c,same).wasOk()&&same==recovered,"repeated recovery verifies and reuses the same completed copy without duplicate clips");
    std::atomic<bool> cancel{true};File sentinel=workspace.getChildFile("sentinel");expect(recoverTakeCheckpoint(c,sentinel,&cancel).failed()&&sentinel==workspace.getChildFile("sentinel"),"cancelled recovery retains prior output and all original files");
    TakeRecoveryScan scan;expect(scanTakeCheckpoints(recordings,scan).wasOk()&&scan.takes.size()==1,"interrupted acknowledged take is discoverable independently of session autosave");expect(completeTakeCheckpoint(c,before,workspace).failed(),"clean completion cannot hide a take absent from the saved project");auto completed=before;Clip clip;clip.track=7;clip.beat=4;clip.length=c.frames/c.rate*c.bpm/60;clip.audioPath=c.audio().getFullPathName();completed.clips.push_back(clip);expect(completeTakeCheckpoint(c,completed,workspace).wasOk()&&scanTakeCheckpoints(recordings,scan).wasOk()&&scan.takes.empty()&&scan.completed==1,"verified final project acknowledgement excludes a normally finished take from interruption review");
    auto resultText=recovered.loadFileAsString();recovered.replaceWithText("changed recovery");expect(recoverTakeCheckpoint(c,same).failed()&&recovered.loadFileAsString()=="changed recovery","modified recovery outputs are never silently overwritten");recovered.replaceWithText(resultText);
    TakeCheckpoint torn;expect(recordedCheckpoint(workspace,torn,1,16001),"record an odd-byte mono take for torn-header recovery");MemoryBlock source;torn.audio().loadFileAsData(source);{FileOutputStream output(torn.audio());output.setPosition(4);output.writeInt(-1);output.setPosition(torn.dataOffset-4);output.writeInt(0);output.setPosition(torn.audio().getSize());output.write("unacknowledged",14);}File repaired;expect(recoverTakeCheckpoint(torn,repaired).wasOk(),"saved checkpoint header recovers acknowledged PCM despite a later torn header and trailing bytes");AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(repaired.getSiblingFile("recovered.wav")));expect(reader&&reader->lengthInSamples==16001&&reader->numChannels==1&&reader->bitsPerSample==24,"recovered mono header contains exact checkpoint length and required odd-byte RIFF padding");
    TakeCheckpoint bad;expect(recordedCheckpoint(workspace,bad),"record source for recovery failure guards");auto snapshot=bad.directory.getChildFile("session.pulse");auto snapshotBytes=snapshot.loadFileAsString();snapshot.replaceWithText("invalid session");expect(recoverTakeCheckpoint(bad,same).failed(),"changed session identity rejects without publishing a recovery");snapshot.replaceWithText(snapshotBytes);auto checkpointText=bad.journal().loadFileAsString();auto v=JSON::parse(checkpointText);v.getDynamicObject()->setProperty("id","../escape");bad.journal().replaceWithText(JSON::toString(v));TakeCheckpoint reject;expect(readTakeCheckpoint(bad.directory,reject).failed(),"checkpoint directory identity cannot redirect file reads or writes");bad.journal().replaceWithText(checkpointText);
    {FileOutputStream output(bad.audio());output.setPosition(bad.dataOffset+(int64)bad.frames*6-1);output.writeByte(99);}expect(recoverTakeCheckpoint(bad,same).failed(),"changed acknowledged tail rejects instead of inventing valid captured audio");
    auto invalid=recordings.getChildFile("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");invalid.createDirectory();invalid.getChildFile("checkpoint.json").replaceWithText("broken");expect(scanTakeCheckpoints(recordings,scan).wasOk()&&scan.invalid==1,"malformed checkpoint is retained and counted during bounded native discovery");
    TakeCheckpoint named;expect(recordedCheckpoint(workspace,named,1,17,true),"a maximum-length song title can be checkpointed before recording");File namedOutput;Project namedProject;expect(recoverTakeCheckpoint(named,namedOutput).wasOk()&&loadProject(namedOutput,namedProject).wasOk()&&namedProject.title.length()<=200&&namedProject.title.contains("recovered take"),"recovery keeps its descriptive title within project persistence bounds");
    auto p=emptyProject();TakeCheckpoint invalidContext;expect(prepareTakeCheckpoint(p,workspace,recordings,-1,0,8000,1,8000,invalidContext).failed()&&prepareTakeCheckpoint(p,workspace,recordings,7,4095,8000,1,80000,invalidContext).failed(),"invalid take lane or timeline capacity fails before arming a writer");
}
static int takeRecoveryProbe(int argc,char** argv){
    if(argc<4)return 2;File workspace(String::fromUTF8(argv[2]));auto expected=File::getCurrentWorkingDirectory().getChildFile("test-output");if(!workspace.isAChildOf(expected))return 3;workspace.createDirectory();String mode=String::fromUTF8(argv[3]);
    if(mode=="recover"){auto directory=File(workspace.getChildFile("take-directory.txt").loadFileAsString().trim());TakeCheckpoint c;auto r=readTakeCheckpoint(directory,c);File result;if(r.wasOk())r=recoverTakeCheckpoint(c,result);if(r.failed()){std::cerr<<r.getErrorMessage()<<"\n";return 1;}workspace.getChildFile("recovered-path.txt").replaceWithText(result.getFullPathName());return 0;}
    auto p=emptyProject();p.bpm=120;p.title="Recording crash fixture";p.patterns[0].lanes[7]={{1,2,65,.8f}};TakeCheckpoint c;int channels=mode=="mono"?1:2;auto r=prepareTakeCheckpoint(p,workspace,workspace.getChildFile("data/Recordings"),7,4,8000,channels,80000,c);if(r.failed())return 4;workspace.getChildFile("take-directory.txt").replaceWithText(c.directory.getFullPathName());Recorder recorder;r=recorder.start(c.audio(),8000,channels,10,&c);if(r.failed())return 5;
    AudioBuffer<float> input(2,257);for(int i=0;i<257;++i){input.setSample(0,i,.25f);input.setSample(1,i,-.125f);}int total=mode=="unflushed"?2000:16000;for(int phase=0;phase<total;phase+=8000){int length=jmin(8000,total-phase);for(int at=0;at<length;at+=257){recorder.capture(input.getReadPointer(0),input.getReadPointer(1),jmin(257,length-at));Thread::sleep(1);}if(mode!="unflushed"&&!waitTake([&]{TakeCheckpoint read;return readTakeCheckpoint(c.directory,read).wasOk()&&read.frames==(uint64_t)(phase+length);}))return 6;}
    if(mode!="unflushed")recorder.capture(input.getReadPointer(0),input.getReadPointer(1),123);workspace.getChildFile("probe-ready.txt").replaceWithText("ready");for(;;)Thread::sleep(10);
}
